// Halo saved-search email: the first 5 listings have link, title, price, date and image; the rest are only ids in the "see all" link.
// Size, rooms and municipality are not separate fields in the email; ParseHaloTitles (Claude) reads them from the title. Price limit: 600 €.
// Numeric HTML entities are decoded too ("40m&#178;" → "40m²"; until 20.11. they showed up as text in the message).
const ent = n => (n > 0 && n <= 0x10ffff ? String.fromCodePoint(n) : '');
const dec = s => String(s)
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => ent(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, d) => ent(Number(d)))
  .replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ').trim();
const out = [];
for (const mail of $input.all()) {
  const html = String(mail.json.html || '');
  // Since 19.11. there is one saved search per municipality; its name ("... - Opština Vračar ...") is in the email → reliable municipality.
  const subj = dec(String(mail.json.subject || ''));
  const pretragaOpstina = ((subj + ' ' + html).match(/Op[sš]tina ([A-Za-zČĆŠĐŽčćšđž]+(?: [A-Za-zČĆŠĐŽčćšđž]+)?)/) || [])[1] || null;
  const blocks = html.split('<td rowspan="3"').slice(1);
  for (const b of blocks) {
    const href = (b.match(/href="(https:\/\/www\.halooglasi\.com\/nekretnine\/izdavanje-stanova\/[^"?]+)/) || [])[1];
    if (!href) continue;
    const hid = href.split('/').pop();
    const naslov = dec((b.match(/font-size: 15px;[^>]*>([^<]+)<\/a>/) || [])[1] || 'Halo oglas');
    const cenaTxt = (b.match(/>\s*([\d.]+)\s*€\s*</) || [])[1];
    const cena = cenaTxt ? Number(cenaTxt.replace(/\./g, '')) : null;
    const d = b.match(/(\d{2})\.(\d{2})\.(\d{4})\./) || [];
    const slika = ((b.match(/src="(https:\/\/img\.halooglasi\.com[^"]+)"/) || [])[1] || '').replace('.com//', '.com/');
    out.push({ json: {
      id: 'halo_' + hid,
      izvor: 'halo',
      url: href,
      naslov,
      cena,
      m2: null,
      sobe: null,
      opstina: '',
      naselje: '',
      namesten: 'nepoznato',
      placanje: 'month',
      objavljeno: d.length ? `${d[3]}-${d[2]}-${d[1]}T00:00:00+01:00` : null,
      slika,
      upisano: new Date().toISOString(),
      prosao_filter: cena === null || cena <= 600,
      pretraga_opstina: pretragaOpstina
    } });
  }
}
// One run can hold the same listing twice: the municipality search and the old combined search (20.11., after the laptop was off all day).
// Remove Duplicates only remembers previous executions, so duplicates within this run are merged here; the copy with the municipality wins.
const byId = new Map();
for (const it of out) {
  const prev = byId.get(it.json.id);
  if (!prev || (!prev.json.pretraga_opstina && it.json.pretraga_opstina)) byId.set(it.json.id, it);
}
return [...byId.values()];

// The email shows only the first 5 new listings; the rest are only ids in the "see all" link (search_ids).
// One message with a button per municipality search, counting only ids that did not come through any email of this run.
// The old combined search (all municipalities, no "Opština" in its name) is skipped: its listings come through the municipality
// searches (20.11.: "5 od 9" from the combined search, all 9 had already arrived).
// The link goes into an inline button, not HTML text: Telegram does not parse button URLs, so & in the query string is fine.
const shown = new Set();
for (const mail of $input.all()) {
  for (const m of String(mail.json.html || '').matchAll(/halooglasi\.com\/nekretnine\/izdavanje-stanova\/[^"?\s]+\/(\d+)/g)) shown.add(m[1]);
}
const out = [];
for (const mail of $input.all()) {
  const html = String(mail.json.html || '');
  const opstina = ((String(mail.json.subject || '') + ' ' + html).match(/Op[sš]tina ([A-Za-zČĆŠĐŽčćšđž]+(?: [A-Za-zČĆŠĐŽčćšđž]+)?)/) || [])[1];
  if (!opstina) continue;
  // "Pogledajte sve" link: /izdavanje-stanova?… (combined search) or /izdavanje-stanova/beograd-zvezdara?… (municipality search).
  const all = (html.match(/href="(https:\/\/www\.halooglasi\.com\/nekretnine\/izdavanje-stanova[^"]*[?&]search_ids=[^"]+)"/) || [])[1];
  if (!all) continue;
  const link = all.replace(/&amp;/g, '&').replace(/&utm_[^&]*/g, '');
  const total = Number((html.match(/pojavilo se <strong>(\d+)<\/strong>/) || [])[1] || 0);
  const ids = ((link.match(/[?&]search_ids=([\d,]+)/) || [])[1] || '').split(',').filter(Boolean);
  const missing = ids.length ? ids.filter(id => !shown.has(id)).length : Math.max(0, total - (html.match(/<td rowspan="3"/g) || []).length);
  if (missing > 0) out.push({ json: { text: `📬 Halo, opština ${opstina}: ${missing} od ${ids.length || total} novih oglasa nije u mejlu (mejl prikazuje samo 5). Otvori ih dugmetom ispod.`, link } });
}
return out;

const items = $input.all();
const ndjson = items.map(i => JSON.stringify(i.json)).join('\n');
const metadata = {
  configuration: {
    load: {
      destinationTable: { projectId: 'stan-hunter', datasetId: 'stan_hunter', tableId: 'listings' },
      sourceFormat: 'NEWLINE_DELIMITED_JSON',
      writeDisposition: 'WRITE_APPEND',
      ignoreUnknownValues: true
    }
  }
};
return [{ json: { metadata, ndjson, count: items.length } }];

