// Claude's reading of the titles merged into the listings by id; values are validated, anything odd stays unknown.
// The municipality of the saved search (from the email) wins over Claude. Filter is the same as for the other sources.
const base = $('RemoveDuplicateHalo').all();
const blocks = Array.isArray($json.content) ? $json.content : [];
const raw = String($json.merged_response || blocks.filter(c => c.type === 'text').map(c => c.text).join('') || $json.text || '');
let parsed = {};
try {
  const p = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
  for (const o of (Array.isArray(p.oglasi) ? p.oglasi : [])) if (o && o.id) parsed[o.id] = o;
} catch (e) { parsed = {}; }
const num = (v, min, max) => { const n = Number(v); return v === null || v === undefined || v === '' || !Number.isFinite(n) || n < min || n > max ? null : n; };
const str = v => typeof v === 'string' && v.trim() ? v.trim().slice(0, 60) : '';
const NAM = ['da', 'polunamešten', 'ne', 'nepoznato'];
return base.map(({ json: j }) => {
  const p = parsed[j.id] || {};
  const { pretraga_opstina, ...rest } = j;
  const m2 = num(p.m2, 10, 500);
  const sobe = num(p.sobe, 0.5, 10);
  const namesten = NAM.includes(p.namesten) ? p.namesten : 'nepoznato';
  const out = { ...rest, opstina: pretraga_opstina || str(p.opstina), naselje: str(p.naselje), m2, sobe, namesten };
  out.prosao_filter = (out.cena === null || out.cena <= 600) && (m2 === null || m2 >= 30) && (sobe === null || sobe >= 1.5) && namesten !== 'ne';
  return { json: out };
});

// Photo quality from `Enrich - photo quality (Claude vision)` (same sub-workflow as the Orchestrator) merged by id.
// If the photo step fails or returns nothing, listings continue without it.
const photos = {};
for (const i of $input.all()) if (i.json && i.json.id && i.json.photo_ok === true) photos[i.json.id] = i.json;
return $('ApplyTitles').all().map(({ json: j }) => {
  const ph = photos[j.id];
  return { json: ph ? { ...j, kvalitet: ph.kvalitet ?? null, kvalitet_opis: ph.kvalitet_opis ?? null } : j };
});

// 0–100 score from the view listings_scored (same formula as everywhere). No score (load failed) → message without it.
const r = $input.first()?.json ?? {};
const fields = (r.schema?.fields || []).map(f => f.name);
const scores = {};
for (const row of r.rows || []) {
  const o = Object.fromEntries(row.f.map((c, i) => [fields[i], c.v]));
  scores[o.id] = { ocena: o.ocena === null ? null : Math.round(Number(o.ocena)), lok: o.lok === null ? null : Number(o.lok) };
}
return $('ApplyHaloPhotos').all().map(i => ({ json: { ...i.json, ocena: scores[i.json.id]?.ocena ?? null, lok: scores[i.json.id]?.lok ?? null } }));

// Same flat already in the database from another site? FindSameFlat returns up to 3 candidates (same price + m² + rooms +
// municipality, last 30 days, newest first). One pair per candidate → Claude vision compares the cover photos (`Dedup - same flat check`).
// FindSameFlat runs once per listing, so its responses are in the same order as the listings.
const responses = $input.all();
const num = v => (v === null || v === undefined ? null : Number(v));
const out = [];
$('FilterHalo').all().forEach(({ json: L }, i) => {
  const r = responses[i]?.json ?? {};
  const fields = (r.schema?.fields || []).map(f => f.name);
  const rows = (r.rows || []).map(row => Object.fromEntries(row.f.map((c, k) => [fields[k], c.v])));
  if (!rows.length) {
    out.push({ json: { listing: L, has_candidate: false }, pairedItem: { item: i } });
    return;
  }
  rows.slice(0, 3).forEach((c, rank) => out.push({
    json: { novi: L, postojeci: { ...c, cena: num(c.cena), m2: num(c.m2), sobe: num(c.sobe), upisano: c.upisano ? Math.round(Number(c.upisano) * 1000) : null, rank }, has_candidate: true },
    pairedItem: { item: i }
  }));
});
return out;

// Verdicts back on the listings. Runs once for listings without a candidate (HasCandidate false, passed through) and once for the
// vision results. Same flat = isti === true for at least one candidate → one-line note pointing to the oldest match;
// otherwise the full message (fail-open: unclear, API error or no photo counts as a different flat).
const items = $input.all();
if (items.every(it => it.json.has_candidate === false)) return items.map(it => ({ json: { ...it.json.listing, dup_isti: false } }));
const fmt = ms => (ms ? DateTime.fromMillis(ms).setZone('Europe/Belgrade').toFormat('dd.MM. HH:mm') : '');
const groups = new Map();
for (const { json: p } of $('PickCandidate').all()) {
  if (p.has_candidate && p.novi && !groups.has(p.novi.id)) groups.set(p.novi.id, { L: p.novi, first: p.postojeci, hit: null, razlog: null });
}
for (const { json: r } of items) {
  const g = r.novi && groups.get(r.novi.id);
  if (!g || !r.postojeci) continue;
  if (r.isti === true) {
    if (!g.hit || (r.postojeci.rank ?? 0) > (g.hit.c.rank ?? 0)) g.hit = { c: r.postojeci, razlog: r.razlog ?? null };
  } else if (!g.razlog && r.razlog) g.razlog = r.razlog;
}
return [...groups.values()].map(({ L, first, hit, razlog }) => {
  const c = hit ? hit.c : first;
  return { json: { ...L, dup_isti: !!hit, dup_razlog: hit ? hit.razlog : razlog, dup_izvor: c.izvor, dup_url: c.url, dup_kada: fmt(c.upisano) } };
});

